class DatCierrePeriodosNomina extends BaseDatCierrePeriodosNomina
{

    public static function obtenerObjDatCierrePeriodos($iddatcierreperiodo)
    {
        return Doctrine::getTable('DatCierrePeriodosNomina')->find($iddatcierreperiodo);
    }

    public static function obtenerListadoDatCierrePeriodos($idfechascierre)
    {
        //Devolviendo el listado
        if (is_array($idfechascierre)) {
            if (!empty($idfechascierre)) {
                $mg = Doctrine_Manager::getInstance();
                $conn = $mg->getCurrentConnection();
                $idfechascierreimplode = implode(',', $idfechascierre);
                $sql = "select dcp.*, dfcp.identidad, dfcp.fechacierre 
                        from mod_nomina.dat_cierreperiodosnomina dcp 
                        inner join mod_nomina.dat_fechascierreperiodos dfcp ON (dfcp.idfechascierre = dcp.idfechascierre)
                        where dcp.idfechascierre in ({$idfechascierreimplode}) order by dcp.idelaborarpagos DESC;";
                $r = $conn->fetchAll($sql);
                return $r;
            }
            return;
        } else {
            return Doctrine_Query::create()
                ->select('*')
                ->from('DatCierrePeriodosNomina')
                //->innerjoin('dcp.DatFechaCierrePeriodo tc')
                ->where('idfechascierre = ?', array($idfechascierre))
                ->fetchArray();
        }

    }

    public static function obtenerListadoPeriodosPagoDatCierrePeriodos($fechascierre, $identidad = 'NULL')
    {
        $idfechascierre = (is_array($fechascierre)) ? implode(',', $fechascierre) : $fechascierre;
        $identidad = (is_array($identidad)) ? implode(',', $identidad) : $identidad;
        $entidad = 'NULL'; 
        if ($identidad != 'NULL') {
            $entidad = "'$identidad'";
        }
        //Devolviendo el listado
        if (!empty($idfechascierre)) {
            $mg = Doctrine_Manager::getInstance();
            $conn = $mg->getCurrentConnection();
            // $sql = "select * from mod_nomina.dat_cierreperiodosnomina where idfechascierre in ({$idfechascierre}) order by idelaborarpagos DESC;";
            $sql = "select cpn.*, dep.identidad
                    from mod_nomina.dat_cierreperiodosnomina as cpn
                        inner JOIN mod_nomina.dat_elaborarpagos dep on (dep.idelaborarpagos = cpn.idelaborarpagos)
                    where
                        cpn.idfechascierre in ({$idfechascierre}) and
                        case
                            when ($entidad is not null) then (dep.identidad in ($identidad))
                                else true END 
                    order by cpn.idelaborarpagos DESC;";
            $r = $conn->fetchAll($sql);
            return $r;
        }
        return;
    }

    public static function obtenerListadoDatFechasCierrePeriodos($identidad)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select * 
                from  mod_nomina.dat_fechascierreperiodos 
                where identidad = ?";
        $r = $conn->fetchAll($sql, array($identidad));
        return $r;
    }

}
